export const componentAttrs = (componentName, {componentCustomisation: {modifiers} = {}}) => (
    [
        `data-component="${componentName}"`,
        (
            Array.isArray(modifiers) && modifiers.length ?
            `data-cm="${modifiers.join('|')}"`
            : ''
        )
    ]
    .filter(Boolean)
    .join(' ')
);
